30	int findMode(const char* str) {
31		struct {
32			int mode;
33			int rate;
34		} modes[] = {
35			{ 0,  6600 },
36			{ 1,  8850 },
37			{ 2, 12650 },
38			{ 3, 14250 },
39			{ 4, 15850 },
40			{ 5, 18250 },
41			{ 6, 19850 },
42			{ 7, 23050 },
43			{ 8, 23850 }
44		};
45		int rate = atoi(str);
46		int closest = -1;
47		int closestdiff = 0;
48		unsigned int i;
49		for (i = 0; i < sizeof(modes)/sizeof(modes[0]); i++) {
50			if (modes[i].rate == rate)
51				return modes[i].mode;
52			if (closest < 0 || closestdiff > abs(modes[i].rate - rate)) {
53				closest = i;
54				closestdiff = abs(modes[i].rate - rate);
55			}
56		}
57		fprintf(stderr, "Using bitrate %d\n", modes[closest].rate);
58		return modes[closest].mode;
59	}
